/* @lc app=leetcode id=3489 lang=kotlin */ class Solution { fun minZeroArray(nums: IntArray, queries: Array<IntArray>): Int = nums.indices.map { i -> if (nums[i] == 0) 0 else BooleanArray(nums[i] + 1).also { it[0] = true }.let { dp -> queries.indexOfFirst { q -> (if (i in q[0]..q[1]) (nums[i] downTo q[2]).forEach { s -> if (dp[s - q[2]]) dp[s] = true }.let { true } else false) && dp[nums[i]] }.let { if (it < 0) Int.MAX_VALUE else it + 1 } } }.max().let { if (it == Int.MAX_VALUE) -1 else it } }